import { getPosts } from '@/lib/api'
import { cacheTag, cacheLife } from 'next/cache'

async function getCachedPosts() {
  "use cache"
  cacheTag('posts')
  cacheLife('hours')
  return getPosts()
}

export default async function Home() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

